// 提取输入参数
const input = $input.item.json;
const topic = input.topic || input.body?.topic || '';
const style = input.style || input.body?.style || '正式';
const length = input.length || input.body?.length || '中等';

// 验证必填字段
if (!topic) {
  throw new Error('主题(topic)不能为空');
}

// 根据长度设置 max_tokens
let maxTokens = 2000;
if (length === '简短' || length === '短') {
  maxTokens = 500;
} else if (length === '中等' || length === '中') {
  maxTokens = 2000;
} else if (length === '详细' || length === '长') {
  maxTokens = 4000;
}

// 构建用户提示词
const userPrompt = `请根据以下主题，生成一份${style}风格的通知。

主题：${topic}

要求：
1. 风格：${style}
2. 长度：${length}（约${maxTokens <= 500 ? '200-300' : maxTokens <= 2000 ? '500-800' : '1000-1500'}字）
3. 格式：标准的正式通知格式，包含标题、正文、落款等
4. 内容：基于主题展开，逻辑清晰，表达准确

请直接生成通知内容，不需要额外说明。`;

return {
  json: {
    topic: topic,
    style: style,
    length: length,
    maxTokens: maxTokens,
    userPrompt: userPrompt
  }
};

