// 解析DeepSeek响应
const aiResponse = $input.item.json;
const inputData = $('准备提示词').item.json;

// 提取AI生成的文本
let noticeContent = '';
if (aiResponse.choices && aiResponse.choices[0] && aiResponse.choices[0].message) {
  noticeContent = aiResponse.choices[0].message.content;
} else if (aiResponse.content) {
  noticeContent = aiResponse.content;
} else if (typeof aiResponse === 'string') {
  noticeContent = aiResponse;
}

// 如果响应为空，返回错误
if (!noticeContent || noticeContent.trim() === '') {
  throw new Error('DeepSeek API 返回内容为空');
}

// 构建返回结果
return {
  json: {
    success: true,
    original_topic: inputData.topic,
    style: inputData.style,
    length: inputData.length,
    formal_notice: noticeContent.trim(),
    generated_at: new Date().toISOString(),
    word_count: noticeContent.trim().length
  }
};
